pub fn spawn_code_editor<'w>(
    parent_cmd: &'w mut ChildSpawnerCommands<'w>,
    initial_text: &str,
    language: &str,
    modifier: impl FnOnce(&mut Node, &mut TextFont, &mut TextColor),
) -> EntityCommands<'w> {
    let mut root_node = Node {
        display: Display::Flex, flex_direction: FlexDirection::Row,
        min_height: Val::Px(200.0), min_width: Val::Px(300.0),
        border: UiRect::all(Val::Px(2.0)), overflow: Overflow::clip(), ..default()
    };
    let mut font = TextFont::default();
    let mut color = TextColor(Color::WHITE);
    modifier(&mut root_node, &mut font, &mut color);

    let mut cmds = parent_cmd.spawn((
        root_node,
        bevy::ui_widgets::Button,
        crate::focus::Focusable,
        ImageNode::default(),
        crate::theme::RuiThemeElement::TextboxBg,
        BorderColor::from(Color::srgb(0.051, 0.051, 0.051)),
        RelativeCursorPosition::default(),
        RuiCodeEditor { 
            text: ropey::Rope::from_str(initial_text),
            language: language.to_string(),
            ..default() 
        },
    ));

    cmds.with_children(|parent| {
        // Left panel: line number gutter
        parent.spawn((
            Node {
                display: Display::Flex, flex_direction: FlexDirection::Column,
                width: Val::Px(50.0), height: Val::Percent(100.0), align_items: AlignItems::FlexEnd,
                padding: UiRect::right(Val::Px(8.0)), overflow: Overflow::clip(), ..default()
            },
            BackgroundColor(Color::srgb(0.08, 0.08, 0.08)), 
        )).with_children(|gutter| {
            gutter.spawn((
                Text::new("1"), font.clone(), TextColor(Color::srgb(0.4, 0.4, 0.4)), RuiCodeEditorGutter,
                Node { position_type: PositionType::Absolute, top: Val::Px(12.0), ..default() },
                Pickable::IGNORE,
            ));
        });

        // Right panel: code text and cursor area
        parent.spawn((
            Node { display: Display::Flex, flex_grow: 1.0, height: Val::Percent(100.0), position_type: PositionType::Relative, overflow: Overflow::clip(), ..default() },
        )).with_children(|editor_area| {
            editor_area.spawn((
                Text::new(""), font, color, RuiCodeEditorText,
                Node { position_type: PositionType::Absolute, left: Val::Px(12.0), top: Val::Px(12.0), ..default() },
                Pickable::IGNORE,
            ));
            editor_area.spawn((
                Node { position_type: PositionType::Absolute, width: Val::Px(3.0), height: Val::Px(20.0), left: Val::Px(12.0), top: Val::Px(12.0), ..default() },
                BackgroundColor(Color::WHITE), Visibility::Hidden, RuiCodeEditorCursor, Pickable::IGNORE,
            ));
        });
    });
    cmds
}

