pub fn spawn_color_picker<'w>(
    parent_cmd: &'w mut ChildSpawnerCommands<'w>,
    initial_color: Color,
    modifier: impl FnOnce(&mut Node),
) -> EntityCommands<'w> {
    let mut s = Node::default();
    modifier(&mut s);

    let mut cmds = parent_cmd.spawn_empty();
    cmds.apply_scene(FeathersColorInput::scene(FeathersColorInputProps::default()));
    cmds.insert((
        ColorInputValue(initial_color),
        RuiColorPicker {
            color: initial_color,
        },
        crate::focus::Focusable,
        Pickable::default(),
    ));
    // Patch only the Node layout properties explicitly customized by the caller.
    cmds.entry::<Node>().and_modify(move |mut node| {
        if s.width != Val::Auto {
            node.width = s.width;
        }
        if s.height != Val::Auto {
            node.height = s.height;
        }
        if s.margin != UiRect::default() {
            node.margin = s.margin;
        }
        if s.padding != UiRect::default() {
            node.padding = s.padding;
        }
        if s.position_type != PositionType::Relative {
            node.position_type = s.position_type;
        }
        if s.left != Val::Auto {
            node.left = s.left;
        }
        if s.right != Val::Auto {
            node.right = s.right;
        }
        if s.top != Val::Auto {
            node.top = s.top;
        }
        if s.bottom != Val::Auto {
            node.bottom = s.bottom;
        }
        if s.flex_grow != 0.0 {
            node.flex_grow = s.flex_grow;
        }
        if s.flex_shrink != 1.0 {
            node.flex_shrink = s.flex_shrink;
        }
    });

    cmds.observe(color_input_self_update);

    cmds.observe(
        |change: On<ValueChange<Color>>, mut q_picker: Query<&mut RuiColorPicker>| {
            if let Ok(mut picker) = q_picker.get_mut(change.source) {
                picker.color = change.value;
            }
        },
    );

    cmds
}

pub fn spawn_context_menu<'w>(
    parent: &'w mut ChildSpawnerCommands<'w>,
    build_items: impl FnOnce(&mut ChildSpawnerCommands),
) {
    let target_id = parent.target_entity();

    let popup_id = parent
        .commands()
        .spawn((
            Node {
                display: Display::None,
                position_type: PositionType::Absolute,
                flex_direction: FlexDirection::Column,
                min_width: Val::Px(160.0),
                width: Val::Auto,
                border: UiRect::all(Val::Px(1.0)),
                padding: UiRect::all(Val::Px(2.0)),
                ..default()
            },
            ImageNode::default(),
            BackgroundColor(Color::srgb(0.15, 0.15, 0.15)),
            BorderColor::from(Color::srgb(0.3, 0.3, 0.3)),
            ZIndex(1000),
            GlobalZIndex(1000),
            Hovered::default(),
            Pickable::default(),
            RuiThemeElement::ContextMenuBg,
        ))
        .with_children(|popup| {
            let mut popup_spawner = popup.reborrow();
            popup_spawner.scrollview(
                |n| {
                    n.width = Val::Percent(100.0);
                    n.align_items = AlignItems::Stretch;
                },
                |scroll| {
                    let mut scroll_spawner = scroll.reborrow();
                    build_items(&mut scroll_spawner);
                },
            );
        })
        .id();

    parent.commands().entity(target_id).insert((
        RuiContextMenu {
            popup_entity: popup_id,
            is_open: false,
        },
        Hovered::default(),
        Pickable::default(),
        RelativeCursorPosition::default(),
    ));
}

